/**
 * Schema for the search_tools tool — progressive discovery of figma.* API methods.
 */
export const searchToolsSchema = {
    name: 'search_tools',
    description: `Search available figma.* API methods for use with the execute tool. Use this to discover method names, parameters, and usage examples.

Recommended workflow:
1. Start with a broad search at "description" detail (default) to find relevant methods
2. Then query the exact method name for full parameter details (e.g. query: "figma.createFrame")

When detail_level is "full" and many methods match, only the top 5 most relevant are returned with full details. The rest are listed by name — use an exact method name query to get full details on any of them.`,
    inputSchema: {
        type: 'object',
        properties: {
            query: {
                type: 'string',
                description: 'Search query — matches against method names and descriptions. Use an exact method name (e.g. "figma.createFrame" or "createFrame") to get just that method\'s full parameter details.',
            },
            category: {
                type: 'string',
                enum: ['create', 'read', 'update', 'delete', 'tokens', 'components', 'accessibility', 'figjam'],
                description: 'Filter by operation category. Use "figjam" for FigJam-specific methods (sections, stickies, shapes).',
            },
            detail_level: {
                type: 'string',
                enum: ['name', 'description', 'full'],
                description: 'Amount of detail: "name" = just names, "description" = names + descriptions, "full" = everything including parameters and examples (capped at top 5 results). Default: "description"',
                default: 'description',
            },
        },
        required: ['query'],
    },
};
